import tracemalloc

class Plain:
    def __init__(self, x, y, z):
        self.x, self.y, self.z = x, y, z

class Slim:
    __slots__ = ("x", "y", "z")
    def __init__(self, x, y, z):
        self.x, self.y, self.z = x, y, z

for cls in (Plain, Slim):
    tracemalloc.start()
    keep = [cls(1, 2, 3) for _ in range(10000)]
    used, _ = tracemalloc.get_traced_memory()
    tracemalloc.stop()
    print(cls.__name__, "has __dict__:", hasattr(keep[0], "__dict__"), "bytes per object ~", round(used / 10000))
